import json, glob, os
# Check predictions/ for the 8 qids across all days
qids = ['383542','439122','654858','820934','593643','217220','85916','625905']
found = {q:None for q in qids}
files = sorted(glob.glob('predictions/*.json'))
print(f"Prediction day-files: {len(files)}  (last: {files[-1] if files else 'none'})")
for f in files:
    try:
        data = json.load(open(f))
    except: continue
    for entry in data:
        q = str(entry.get('question_id'))
        if q in found and found[q] is None:
            found[q] = entry.get('outcomes')
# report
for q in qids:
    o = found[q]
    if o: print(f"{q}: recorded -> {o}")
    else: print(f"{q}: NOT FOUND in any day-file")
EOF
